-- Commerce indexes and the per-store revenue goal.
-- Review and run this yourself. Do not apply it from the app.
-- Do not edit this file in a later phase. Do not apply 0022.
--
-- The goal ring reads platform_settings.revenue_goal_minor for the owner store
-- and tenant_settings.revenue_goal_minor for each reseller store.
-- Both are nullable. A null goal means the store has not set one.
-- The check allows zero or more. Money is USDT minor units (6 decimal places).

alter table platform_settings
  add column if not exists revenue_goal_minor bigint;

alter table platform_settings
  drop constraint if exists platform_settings_revenue_goal_chk;
alter table platform_settings
  add constraint platform_settings_revenue_goal_chk
  check (revenue_goal_minor is null or revenue_goal_minor >= 0);

alter table tenant_settings
  add column if not exists revenue_goal_minor bigint;

alter table tenant_settings
  drop constraint if exists tenant_settings_revenue_goal_chk;
alter table tenant_settings
  add constraint tenant_settings_revenue_goal_chk
  check (revenue_goal_minor is null or revenue_goal_minor >= 0);

-- ---------------------------------------------------------------------------
-- Orders
-- ---------------------------------------------------------------------------

-- Buyer card and order search.
-- Query: select id from orders where customer_id = $1
--        select id from orders where customer_id in (...)
-- Why: no earlier index leads with customer_id. The drawer counts one buyer's
-- orders, and search turns a name into customer ids and then filters orders.
-- Without this, both read the whole orders table.
create index if not exists idx_orders_customer_id
  on orders (customer_id);

-- Owner revenue today, and the goal ring numerator.
-- Query: select quoted_retail_price from orders
--        where payment_status = 'verified' and created_at >= $start_of_day
-- Why: idx_orders_created_at includes unpaid rows. The owner query has no
-- tenant filter, so a partial index on the verified slice answers it.
create index if not exists idx_orders_verified_created
  on orders (created_at desc)
  where payment_status = 'verified';

-- Reseller revenue today, and a store filter limited to verified sales.
-- Query: select quoted_retail_price from orders
--        where tenant_id = $store and payment_status = 'verified'
--          and created_at >= $start_of_day
-- Why: idx_orders_tenant_created includes every payment status. This keeps
-- one store's verified rows together in time order.
create index if not exists idx_orders_tenant_verified_created
  on orders (tenant_id, created_at desc)
  where payment_status = 'verified';

-- Fulfilling chip, Failed chip, and attention=fulfillment.
-- Query: select id from orders
--        where fulfillment_status in
--          ('queued','processing','manual_pending','supplier_pending','outcome_unknown','failed')
--        order by created_at desc
-- Why: the older partial indexes cover only queued and manual_pending.
-- supplier_pending, processing, outcome_unknown, and failed have no
-- created_at index, so the chip counts and the stuck queue would sort a scan.
create index if not exists idx_orders_fulfillment_open
  on orders (fulfillment_status, created_at desc)
  where fulfillment_status in (
    'queued', 'processing', 'manual_pending', 'supplier_pending', 'outcome_unknown', 'failed'
  );

-- Delivered chip, attention=delivery, and the failed-delivery part of Needs attention.
-- Query: select id from orders
--        where delivery_status in ('sent','review_required','retry_pending','unreachable')
--        order by created_at desc
-- Why: idx_orders_delivery_retry is only retry_pending and unreachable, and it
-- has no created_at. Delivered (sent) and the manual queue (review_required)
-- need the status and the time order together.
create index if not exists idx_orders_delivery_active
  on orders (delivery_status, created_at desc)
  where delivery_status in ('sent', 'review_required', 'retry_pending', 'unreachable');

-- Store filter "API".
-- Query: select id from orders where channel = 'api' order by created_at desc
-- Why: idx_orders_channel_status leads with channel but does not include
-- created_at, so the API slice is filtered and then sorted. The list is
-- always ordered by created_at.
create index if not exists idx_orders_channel_created
  on orders (channel, created_at desc);

-- Order list filtered by product, including unpaid orders.
-- Query: select id from orders where product_id in (...) order by created_at desc
-- Why: idx_orders_product_verified is only payment_status = 'verified' and has
-- no created_at. Search by product must return every order for that product.
create index if not exists idx_orders_product_created
  on orders (product_id, created_at desc);

-- Inventory "sold in the last 30 days".
-- Query: select product_id from orders
--        where product_id = $1 and payment_status = 'verified'
--          and created_at >= $thirty_days_ago
-- Why: the verified product index has no created_at, so a velocity read pulls
-- every historical sale and then throws away the older rows. This range-scans
-- the recent verified sales of one product.
create index if not exists idx_orders_product_sold_recent
  on orders (product_id, created_at desc)
  where payment_status = 'verified';

-- Median delivery time.
-- Query: select order_id, created_at from order_events
--        where track = 'delivery' and to_status = 'sent' and created_at >= $start_of_day
-- Why: idx_order_events_order leads with order_id. The median does not know
-- the order id first. It reads today's sent events and compares them with
-- orders.created_at.
create index if not exists idx_order_events_delivery_sent
  on order_events (created_at desc)
  where track = 'delivery' and to_status = 'sent';

-- Drawer replacement history for one order.
-- Query: select id, status from replacement_requests
--        where order_id = $1 order by created_at desc
-- Why: replacement_requests_one_open_uidx only includes pending and approved.
-- The drawer also reads replaced and rejected rows.
create index if not exists idx_replacement_requests_order
  on replacement_requests (order_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Products
-- ---------------------------------------------------------------------------

-- Category chips on every stage, not only published.
-- Query: select category from products where status = $stage
-- Why: idx_products_status_category is partial to status = 'published'.
-- Paused, archived, and draft chip counts would scan products.
create index if not exists idx_products_status_category_all
  on products (status, category);

-- Inventory needs-attention: tracked stock at or below the reorder point.
-- Query: select id, stock_count from products
--        where stock_unlimited = false and status <> 'archived'
--        order by stock_count
-- Why: no earlier product index includes stock_count. The attention list is
-- exactly the tracked, non-archived products, ordered by how few are left.
create index if not exists idx_products_tracked_stock
  on products (stock_count)
  where stock_unlimited = false and status <> 'archived';

-- Owner products that were not imported from a supplier, ordered by title.
-- Query: select id from products
--        where supplier_id is null and status = $stage
--        order by title
-- Why: idx_products_supplier only includes supplier_id is not null, so the
-- own-catalog list cannot use it.
create index if not exists idx_products_own_status
  on products (status, title)
  where supplier_id is null;

-- Product editor file list.
-- Query: select id from product_assets where product_id = $1 order by created_at desc
-- Why: product_id is not the primary key and had no index. Opening a product
-- scanned every file row.
create index if not exists idx_product_assets_product
  on product_assets (product_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Suppliers
-- ---------------------------------------------------------------------------

-- Import catalog, default sort and paging.
-- Query: select id from supplier_products
--        where supplier_id = $1 order by name
--        offset $page limit $page_size
-- Why: idx_supplier_products_supplier is (supplier_id, review_status) and
-- idx_supplier_products_sku is (supplier_id, supplier_sku). Neither orders by
-- name, so each page sorted the supplier's whole catalog.
create index if not exists idx_supplier_products_supplier_name
  on supplier_products (supplier_id, name);

-- In stock / out of stock, and the last-synced sort.
-- Query: select id from supplier_products
--        where supplier_id = $1 and in_stock = $2
--        order by last_synced_at desc
-- Why: no earlier supplier_products index includes in_stock or last_synced_at.
create index if not exists idx_supplier_products_supplier_stock
  on supplier_products (supplier_id, in_stock, last_synced_at desc);

-- Not published filter.
-- Query: select id from supplier_products
--        where supplier_id = $1 and product_id is null
--        order by name
-- Why: published vs not published is product_id null or not. The unique
-- (supplier_id, supplier_sku) index does not identify unpublished rows.
create index if not exists idx_supplier_products_unpublished
  on supplier_products (supplier_id, name)
  where product_id is null;

-- Supplier order monitor.
-- Query: select order_id, status, error from fulfillment_attempts
--        where method = 'supplier' order by started_at desc
-- Why: idx_fulfillment_order leads with order_id. The monitor lists recent
-- supplier attempts without an order id.
create index if not exists idx_fulfillment_supplier_started
  on fulfillment_attempts (started_at desc)
  where method = 'supplier';

-- ---------------------------------------------------------------------------
-- No new RLS policies.
-- 0033 adds columns and indexes only. It does not add a table.
-- platform_settings, tenant_settings, orders, order_events, products,
-- product_assets, supplier_products, fulfillment_attempts, and
-- replacement_requests already have row level security enabled.
-- Dashboard routes use the service role, which bypasses RLS, and they scope
-- the tenant in application code. A new policy would not change who can read
-- these rows. A policy that mentioned revenue_goal_minor would also be wrong
-- during the window before this migration is applied.
-- ---------------------------------------------------------------------------
